insert into units(id,level,ord,title,tip,icon,color) values
(1,0,1,'{"ar":"الحروف والتهجئة (A–Z وÄ Ö Ü ß)","en":"Alphabet & spelling (A–Z and Ä Ö Ü ß)","fr":"Alphabet et épellation (A–Z et Ä Ö Ü ß)"}'::jsonb,'{"ar":"ä ö ü تسمى Umlaute: ä ≈ e ممدودة [ɛː]، ö = استدر الشفتين وقل e [øː]، ü = استدر الشفتين وقل i [yː]. أما ß فتُنطق ss [s] وتُكتب بعد المدّ والأصوات المركبة. الأسماء بين قوسين تقريبية.","en":"ä ö ü are Umlaute: ä ≈ long ‘e’ [ɛː], ö = round your lips and say ‘e’ [øː], ü = round your lips and say ‘ee’ [yː]. ß sounds like ‘ss’ [s], written after long vowels and diphthongs. Respelled names are approximate.","fr":"ä ö ü sont des Umlaute : ä ≈ e long [ɛː], ö = arrondissez les lèvres et dites e [øː], ü = arrondissez les lèvres et dites i [yː]. ß se prononce ss [s]. Les noms transcrits sont approximatifs."}'::jsonb,'🔤','#ff6b6b'),
(2,0,2,'{"ar":"النطق والأصوات (ä ö ü ß ch ei eu…)","en":"Pronunciation & sounds (ä ö ü ß ch ei eu…)","fr":"Prononciation et sons (ä ö ü ß ch ei eu…)"}'::jsonb,'{"ar":"بعد a و o و u و au: ach-Laut [x]. بعد غيرها (i e ä ö ü ei eu äu l n r): ich-Laut [ç].","en":"After a, o, u, au: ach-Laut [x]. After other sounds (i e ä ö ü ei eu äu l n r): ich-Laut [ç].","fr":"Après a, o, u, au : ach-Laut [x]. Après les autres (i e ä ö ü ei eu äu l n r) : ich-Laut [ç]."}'::jsonb,'🗣️','#ffa94d'),
(3,0,3,'{"ar":"الأرقام","en":"Numbers","fr":"Nombres"}'::jsonb,'{"ar":"الآحاد قبل العشرات: 34 = vier-und-dreißig (4 + و + 30). 16 = sechzehn و17 = siebzehn و30 = dreißig.","en":"Ones come before tens: 34 = vier-und-dreißig (4 + and + 30). 16 = sechzehn, 17 = siebzehn, 30 = dreißig.","fr":"Les unités avant les dizaines : 34 = vier-und-dreißig (4 + et + 30). 16 = sechzehn, 17 = siebzehn, 30 = dreißig."}'::jsonb,'🔢','#51cf66'),
(4,0,4,'{"ar":"التحيات والعبارات الأساسية","en":"Greetings & essential phrases","fr":"Salutations et phrases essentielles"}'::jsonb,null,'👋','#339af0'),
(5,0,5,'{"ar":"الأيام والشهور والفصول والساعة","en":"Days, months, seasons & time","fr":"Jours, mois, saisons et heure"}'::jsonb,'{"ar":"الساعة غير الرسمية (مثال 15:00 = drei Uhr)","en":"Informal clock (example: 15:00 = drei Uhr)","fr":"L’heure informelle (exemple : 15:00 = drei Uhr)"}'::jsonb,'📅','#845ef7'),
(6,0,6,'{"ar":"كلمات يومية بالصور (ألوان، حيوانات، طعام…)","en":"Everyday words with pictures","fr":"Mots du quotidien en images"}'::jsonb,'{"ar":"الألوان تدل على الجنس: der مذكر (أزرق) · die مؤنث (وردي) · das محايد (أخضر). احفظ الاسم دائمًا مع أداته.","en":"Colours show gender: der masculine (blue) · die feminine (pink) · das neuter (green). Always learn the noun with its article.","fr":"Les couleurs indiquent le genre : der masculin (bleu) · die féminin (rose) · das neutre (vert). Apprenez toujours le nom avec son article."}'::jsonb,'🖼️','#f06595'),
(7,1,1,'{"ar":"تصريف الأفعال","en":"Verb conjugation","fr":"Conjugaison des verbes"}'::jsonb,'{"ar":"-e · -st · -t · -en · -t · -en   (ich lerne · du lernst · er lernt · wir lernen · ihr lernt · sie lernen)","en":"-e · -st · -t · -en · -t · -en   (ich lerne · du lernst · er lernt · wir lernen · ihr lernt · sie lernen)","fr":"-e · -st · -t · -en · -t · -en   (ich lerne · du lernst · er lernt · wir lernen · ihr lernt · sie lernen)"}'::jsonb,'✏️','#20c997'),
(8,1,2,'{"ar":"الفعل sein (يكون)","en":"The verb sein (to be)","fr":"Le verbe sein (être)"}'::jsonb,'{"ar":"ich bin · du bist · er/sie/es ist · wir sind · ihr seid · sie/Sie sind","en":"ich bin · du bist · er/sie/es ist · wir sind · ihr seid · sie/Sie sind","fr":"ich bin · du bist · er/sie/es ist · wir sind · ihr seid · sie/Sie sind"}'::jsonb,'🧩','#ff6b6b'),
(9,1,3,'{"ar":"الأدوات der/die/das","en":"Articles der/die/das","fr":"Articles der/die/das"}'::jsonb,'{"ar":"كل اسم ألماني له جنس: der مذكر · die مؤنث · das محايد. احفظ الاسم دائمًا مع أداته.","en":"Every noun has a gender: der masculine · die feminine · das neuter. Always learn a noun with its article.","fr":"Chaque nom a un genre : der masculin · die féminin · das neutre. Apprenez toujours le nom avec son article."}'::jsonb,'🎯','#ffa94d'),
(10,1,4,'{"ar":"الفعل haben (يملك)","en":"The verb haben (to have)","fr":"Le verbe haben (avoir)"}'::jsonb,'{"ar":"ich habe · du hast · er/sie/es hat · wir haben · ihr habt · sie/Sie haben","en":"ich habe · du hast · er/sie/es hat · wir haben · ihr habt · sie/Sie haben","fr":"ich habe · du hast · er/sie/es hat · wir haben · ihr habt · sie/Sie haben"}'::jsonb,'🧠','#51cf66'),
(11,2,1,'{"ar":"الأفعال المساعدة","en":"Modal verbs","fr":"Verbes modaux"}'::jsonb,'{"ar":"ich kann · du kannst · er kann · wir können · ihr könnt · sie können","en":"ich kann · du kannst · er kann · wir können · ihr könnt · sie können","fr":"ich kann · du kannst · er kann · wir können · ihr könnt · sie können"}'::jsonb,'✏️','#339af0'),
(12,2,2,'{"ar":"الحالة الدَّتيفية","en":"The dative","fr":"Le datif"}'::jsonb,'{"ar":"بعد mit وnach وbei وseit وvon وzu وaus نستعمل الدَّتيف: dem للمذكر والمحايد، der للمؤنث.","en":"After mit, nach, bei, seit, von, zu, aus use the dative: dem (m/n), der (f).","fr":"Après mit, nach, bei, seit, von, zu, aus : datif → dem (m/n), der (f)."}'::jsonb,'🧩','#845ef7'),
(13,2,3,'{"ar":"صيغة الجمع","en":"Plurals","fr":"Les pluriels"}'::jsonb,null,'🎯','#f06595'),
(14,2,4,'{"ar":"الماضي التام (Perfekt)","en":"Perfect tense","fr":"Le Perfekt"}'::jsonb,'{"ar":"الماضي التام = haben/sein + التصريف الثالث: Ich habe gegessen. Ich bin gegangen (أفعال الحركة والتغيّر مع sein).","en":"Perfekt = haben/sein + Partizip II: Ich habe gegessen. Ich bin gegangen (movement/change verbs take sein).","fr":"Perfekt = haben/sein + participe II : Ich habe gegessen. Ich bin gegangen (mouvement/changement → sein)."}'::jsonb,'🧠','#20c997'),
(15,3,1,'{"ar":"الماضي البسيط","en":"Simple past","fr":"Le prétérit"}'::jsonb,'{"ar":"الماضي البسيط يُستعمل غالبًا في الكتابة: ging, kam, sah… احفظ الأشكال الشاذة.","en":"Simple past (mostly written): ging, kam, sah… Learn the irregular forms by heart.","fr":"Prétérit (surtout écrit) : ging, kam, sah… Apprenez les formes irrégulières."}'::jsonb,'✏️','#ff6b6b'),
(16,3,2,'{"ar":"أفعال مع حروف جر","en":"Verbs + prepositions","fr":"Verbes + prépositions"}'::jsonb,null,'🧩','#ffa94d'),
(17,3,3,'{"ar":"تصريف الصفات","en":"Adjective endings","fr":"Terminaisons des adjectifs"}'::jsonb,null,'🎯','#51cf66'),
(18,3,4,'{"ar":"أدوات الربط","en":"Connectors","fr":"Connecteurs"}'::jsonb,'{"ar":"weil وdass وobwohl وwenn وals وob وdamit → يذهب الفعل المصرّف إلى نهاية الجملة.","en":"weil, dass, obwohl, wenn, als, ob, damit → the conjugated verb goes to the END of the clause.","fr":"weil, dass, obwohl, wenn, als, ob, damit → le verbe conjugué va à la FIN."}'::jsonb,'🧠','#339af0'),
(19,3,5,'{"ar":"الجمل الموصولة","en":"Relative clauses","fr":"Propositions relatives"}'::jsonb,null,'🚀','#845ef7'),
(20,4,1,'{"ar":"صيغة التمنّي Konjunktiv II","en":"Konjunktiv II","fr":"Le Konjunktiv II"}'::jsonb,'{"ar":"للتمنّي والشروط غير الواقعية: wäre, hätte, käme, würde + مصدر.","en":"Wishes and unreal conditions: wäre, hätte, käme, würde + infinitive.","fr":"Souhaits et irréel : wäre, hätte, käme, würde + infinitif."}'::jsonb,'✏️','#f06595'),
(21,4,2,'{"ar":"المبني للمجهول","en":"The passive","fr":"Le passif"}'::jsonb,null,'🧩','#20c997'),
(22,4,3,'{"ar":"الحالة الإضافية","en":"The genitive","fr":"Le génitif"}'::jsonb,'{"ar":"wegen وtrotz وwährend وstatt + الإضافة: des للمذكر والمحايد (+ s) وder للمؤنث والجمع.","en":"wegen, trotz, während, statt + genitive: des (m/n) + -s/-es, der (f/pl).","fr":"wegen, trotz, während, statt + génitif : des (m/n) + -s/-es, der (f/pl)."}'::jsonb,'🎯','#ff6b6b'),
(23,5,1,'{"ar":"الكلام غير المباشر","en":"Reported speech","fr":"Le discours indirect"}'::jsonb,null,'✏️','#ffa94d'),
(24,5,2,'{"ar":"المفردات المتقدمة","en":"Advanced vocabulary","fr":"Vocabulaire avancé"}'::jsonb,null,'🧩','#51cf66'),
